#!/usr/bin/env python3
"""Compile the private production watermark paths with their gate OFF and ON.

The success/failure functions, caller predicate, data structs, and sample gate
are extracted unchanged. Only kernel boundary effects are replaced by counters;
the production sampling/bucket conditions are never reproduced in the fixture.
The saved pre-patch hashes also prove that failure/caller behavior was untouched.
"""
from pathlib import Path
import hashlib
import json
import re
import subprocess
import tempfile

ROOT = Path('/home/t4ce/Repositories/TRUEOS-codex-alloc-gates-build/TRUEOS')
BASELINE = Path('/tmp/trueos-watermark-gate-baseline-20261031.json')


def item(source, pattern):
    match = re.search(pattern, source, re.M)
    assert match, pattern
    brace = source.index('{', match.end())
    ending = re.search(r'^}\s*\n', source[brace:], re.M)
    assert ending, pattern
    return source[match.start():brace + ending.end()]


HARNESS = r'''#![allow(dead_code)]
use core::alloc::Layout;
use core::sync::atomic::{AtomicBool, AtomicU32, AtomicU64, AtomicUsize, Ordering};

mod allcaps { pub mod hv { @FLAG@ } }
#[path = "@WATERMARK_PATH@"]
mod watermark;

static CLOCK_READS: AtomicUsize = AtomicUsize::new(0);
static DOMAIN_ENTRIES: AtomicUsize = AtomicUsize::new(0);
static HEAP_SCANS: AtomicUsize = AtomicUsize::new(0);
static TRACE_READS: AtomicUsize = AtomicUsize::new(0);
static INFO_LOGS: AtomicUsize = AtomicUsize::new(0);
static WARN_LOGS: AtomicUsize = AtomicUsize::new(0);
static IDENTITY_READS: AtomicUsize = AtomicUsize::new(0);
static NOW_MS: AtomicU64 = AtomicU64::new(0);
static FREE_BYTES: AtomicUsize = AtomicUsize::new(64 * 1024 * 1024);
static HULL: AtomicBool = AtomicBool::new(false);

#[macro_export]
macro_rules! log_info {
    (target: $target:literal; $($args:tt)*) => {{
        crate::INFO_LOGS.fetch_add(1, Ordering::Relaxed);
        let _ = format_args!($($args)*);
    }};
}
#[macro_export]
macro_rules! log_warn {
    (target: $target:literal; $($args:tt)*) => {{
        crate::WARN_LOGS.fetch_add(1, Ordering::Relaxed);
        let _ = format_args!($($args)*);
    }};
}
mod hv {
    pub fn current_hull_guest_context_vm_id() -> Option<u8> {
        super::IDENTITY_READS.fetch_add(1, super::Ordering::Relaxed);
        super::HULL.load(super::Ordering::Relaxed).then_some(1)
    }
}
mod r { pub mod input_timing {
    pub fn now_ms() -> u64 {
        crate::CLOCK_READS.fetch_add(1, crate::Ordering::Relaxed);
        crate::NOW_MS.load(crate::Ordering::Relaxed)
    }
} }

@CONSTANTS@
static HV_GUEST_ALLOC_FREE_BUCKET_BY_VM: [AtomicU32; 8] =
    [const { AtomicU32::new(HV_GUEST_ALLOC_BUCKET_INIT) }; 8];
static HV_GUEST_ALLOC_SAMPLE_BY_VM: [watermark::SampleGate; 8] =
    [const { watermark::SampleGate::new() }; 8];

#[derive(Copy, Clone, Debug)]
pub enum HeapSourceKind { Arena }
#[derive(Copy, Clone, Debug)]
@HEAP_STATS@
@ALLOC_TRACE@

fn with_host_alloc_domain_strong<T>(f: impl FnOnce() -> T) -> T {
    DOMAIN_ENTRIES.fetch_add(1, Ordering::Relaxed);
    f()
}
fn hv_guest_heap_stats(_: u8) -> HeapStats {
    HEAP_SCANS.fetch_add(1, Ordering::Relaxed);
    let bytes = FREE_BYTES.load(Ordering::Relaxed);
    HeapStats {
        heap_start: 0, heap_end: bytes, phys_start: 0, usable_start: 0,
        usable_total: bytes, free_bytes: bytes, largest_free_block: bytes,
        free_blocks: 3, initialized: true, source: HeapSourceKind::Arena,
    }
}
fn last_alloc_trace() -> AllocTrace {
    TRACE_READS.fetch_add(1, Ordering::Relaxed);
    AllocTrace {
        seq: 1, caller_rip: 0, caller_rip_1: 0, caller_rip_2: 0,
        layout_size: 8, layout_align: 8, stage: 0, head_ptr: 0,
        block_ptr: 0, block_size: 0, block_next: 0, payload_start: 0,
        aligned_used: 0,
    }
}

@PREDICATE@
@SUCCESS@
@FAILURE@

fn reset() {
    for counter in [&CLOCK_READS, &DOMAIN_ENTRIES, &HEAP_SCANS, &TRACE_READS,
        &INFO_LOGS, &WARN_LOGS, &IDENTITY_READS] {
        counter.store(0, Ordering::Relaxed);
    }
    NOW_MS.store(0, Ordering::Relaxed);
    FREE_BYTES.store(64 * 1024 * 1024, Ordering::Relaxed);
    HULL.store(false, Ordering::Relaxed);
}
fn counters() -> [usize; 7] {
    [&CLOCK_READS, &DOMAIN_ENTRIES, &HEAP_SCANS, &TRACE_READS,
        &INFO_LOGS, &WARN_LOGS, &IDENTITY_READS].map(|x| x.load(Ordering::Relaxed))
}
fn success(vm: u8, bytes: usize) {
    log_hv_guest_alloc_watermark(vm, Layout::from_size_align(bytes, 8).unwrap(),
        core::ptr::dangling_mut(), "fixture");
}

#[cfg(not(watermark_probes_enabled))]
#[test]
fn disabled_success_never_reads_clock_enters_domain_scans_heap_reads_trace_or_logs() {
    reset();
    assert!(!allcaps::hv::HV_NATIVE_ALLOC_WATERMARK_PROBES_ENABLED);
    for vm in [0, 1, 255] {
        for bytes in [8, 1024 * 1024, 32 * 1024 * 1024] {
            success(vm, bytes);
        }
    }
    assert_eq!(counters(), [0; 7]);
    assert!(HV_GUEST_ALLOC_FREE_BUCKET_BY_VM.iter()
        .all(|slot| slot.load(Ordering::Relaxed) == HV_GUEST_ALLOC_BUCKET_INIT));
}

#[cfg(watermark_probes_enabled)]
#[test]
fn enabled_ordinary_sampling_limits_walks_and_keeps_quiet_bucket_silent() {
    reset();
    success(0, 8);
    success(0, 8);
    NOW_MS.store(999, Ordering::Relaxed);
    success(0, 8);
    NOW_MS.store(1000, Ordering::Relaxed);
    success(0, 8);
    assert_eq!(counters(), [4, 2, 2, 1, 1, 0, 0]);
}

#[cfg(watermark_probes_enabled)]
#[test]
fn enabled_large_requests_keep_immediate_samples_and_delay_following_small_walk() {
    reset();
    success(1, 1024 * 1024);
    success(1, 1024 * 1024);
    success(1, 8);
    assert_eq!(counters(), [3, 2, 2, 2, 2, 0, 0]);
}

#[cfg(watermark_probes_enabled)]
#[test]
fn enabled_changed_bucket_retains_success_report() {
    reset();
    success(2, 8);
    NOW_MS.store(1000, Ordering::Relaxed);
    success(2, 8);
    FREE_BYTES.store(32 * 1024 * 1024, Ordering::Relaxed);
    NOW_MS.store(2000, Ordering::Relaxed);
    success(2, 8);
    assert_eq!(counters(), [3, 3, 3, 2, 2, 0, 0]);
}

#[test]
fn failure_diagnostic_bypasses_success_gate_and_keeps_both_warning_records() {
    reset();
    log_hv_guest_alloc_failure(3, Layout::from_size_align(128, 8).unwrap(), "fixture");
    assert_eq!(counters(), [0, 1, 1, 1, 0, 2, 0]);
}

#[test]
fn caller_predicate_preserves_native_and_hull_identity_semantics() {
    reset();
    assert!(should_log_hv_guest_alloc_success());
    HULL.store(true, Ordering::Relaxed);
    assert!(!should_log_hv_guest_alloc_success());
    assert_eq!(counters(), [0, 0, 0, 0, 0, 0, 2]);
}
'''


def main():
    baseline = json.loads(BASELINE.read_text())
    source = (ROOT / 'src/allocators.rs').read_text()
    allcaps = (ROOT / 'src/allcaps.rs').read_text()
    functions = {
        'failure': item(source, r'^fn log_hv_guest_alloc_failure\('),
        'predicate': item(source, r'^fn should_log_hv_guest_alloc_success\('),
        'explicit_alloc': item(source, r'^pub unsafe fn alloc_raw_hv_guest\('),
        'watermark': item(source, r'^fn log_hv_guest_alloc_watermark\('),
    }
    for name in ('failure', 'predicate', 'explicit_alloc'):
        assert functions[name] == baseline['functions'][name], f'changed {name}'
    guard = '    if !crate::allcaps::hv::HV_NATIVE_ALLOC_WATERMARK_PROBES_ENABLED { return; }\n'
    assert functions['watermark'].count(guard) == 1
    assert functions['watermark'].replace(guard, '', 1) == baseline['functions']['watermark']
    declaration = re.search(r'^    pub const HV_NATIVE_ALLOC_WATERMARK_PROBES_ENABLED: bool = false;$',
                            allcaps, re.M)
    assert declaration, 'private gate must default OFF'
    for existing in ('HV_ALLOC_DETAIL_PROBES_ENABLED', 'CODEX_ALLOC_ABI_PROBES_ENABLED'):
        assert re.search(rf'pub const {existing}: bool = false;', allcaps)
    addition = ('    // Success watermarks walk the fragmented guest heap; retain failure reports.\n'
                '    pub const HV_NATIVE_ALLOC_WATERMARK_PROBES_ENABLED: bool = false;\n')
    assert hashlib.sha256(allcaps.replace(addition, '', 1).encode()).hexdigest() == baseline['sha256']['src/allcaps.rs']
    assert hashlib.sha256(source.replace(guard, '', 1).encode()).hexdigest() == baseline['sha256']['src/allocators.rs']
    constants = '\n'.join(re.findall(r'^const HV_GUEST_ALLOC_BUCKET_(?:SHIFT|INIT):.*$', source, re.M))
    assert len(constants.splitlines()) == 2
    common = HARNESS.replace('@WATERMARK_PATH@', str(ROOT / 'src/allocators/watermark.rs'))
    replacements = {
        '@CONSTANTS@': constants,
        '@HEAP_STATS@': item(source, r'^pub struct HeapStats\b'),
        '@ALLOC_TRACE@': item(source, r'^pub struct AllocTrace\b'),
        '@PREDICATE@': functions['predicate'],
        '@SUCCESS@': functions['watermark'],
        '@FAILURE@': functions['failure'],
    }
    for key, value in replacements.items():
        common = common.replace(key, value)
    with tempfile.TemporaryDirectory(prefix='trueos-watermark-gate-') as td:
        td = Path(td)
        for enabled in (False, True):
            # Only the compile-time flag changes. All production function bodies stay exact.
            flag = declaration.group().strip().replace('= false;', f'= {str(enabled).lower()};')
            rs = td / f'watermark_{enabled}.rs'
            binary = td / f'watermark_{enabled}'
            rs.write_text(common.replace('@FLAG@', flag))
            command = ['rustc', '--edition=2024', '--test', str(rs), '-o', str(binary)]
            if enabled:
                command += ['--cfg', 'watermark_probes_enabled']
            subprocess.run(command, check=True)
            subprocess.run([str(binary), '--test-threads=1'], check=True)
    print('Source contracts PASS: only private flag+success early return; failure/predicate/caller exact.')
    receipt = {'baseline': str(BASELINE), 'root': str(ROOT), 'flags': {
        'HV_ALLOC_DETAIL_PROBES_ENABLED': False,
        'CODEX_ALLOC_ABI_PROBES_ENABLED': False,
        'HV_NATIVE_ALLOC_WATERMARK_PROBES_ENABLED': False},
        'sha256': {p: hashlib.sha256((ROOT / p).read_bytes()).hexdigest()
                   for p in ('src/allcaps.rs', 'src/allocators.rs')}}
    out = Path('/tmp/trueos-watermark-gate-validation-20261031.json')
    out.write_text(json.dumps(receipt, indent=2) + '\n')
    print(json.dumps(receipt, indent=2))


if __name__ == '__main__':
    main()

